import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class InputReader {
        private final byte[] buffer = new byte[1 << 15];
        private int bufferIndex = 0, bufferLength = 0;
        private final InputStream inputStream;

        InputReader(InputStream is) { inputStream = is; }

        private int readByte() throws IOException {
            if (bufferIndex >= bufferLength) {
                bufferLength = inputStream.read(buffer);
                bufferIndex = 0;
                if (bufferLength <= 0) return -1;
            }
            return buffer[bufferIndex++];
        }

        int readInt() throws IOException {
            int ch;
            while ((ch = readByte()) <= 32) if (ch == -1) return -1;
            int value = 0;
            while (ch > 32) {
                value = value * 10 + ch - '0';
                ch = readByte();
            }
            return value;
        }
    }

    InputReader reader;

    public static void main(String[] args) {
        CF1187G instance = new CF1187G();
        instance.reader = new InputReader(System.in);
        instance.execute();
        instance.flush();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adjacency;
    int totalNodes, totalEdges;
    int[] potential, distance, predecessor;
    int[] edgeStart, edgeEnd, edgeXor, edgeWeight;
    int[] edgeCapacity;

    void prepare(int nodes, int edges) {
        adjacency = new ArrayList[nodes];
        for (int i = 0; i < nodes; i++) adjacency[i] = new ArrayList<>();
        potential = new int[nodes];
        distance = new int[nodes];
        predecessor = new int[nodes];
        edgeStart = new int[edges];
        edgeEnd = new int[edges];
        edgeXor = new int[edges];
        edgeWeight = new int[edges];
        edgeCapacity = new int[edges * 2];
        totalEdges = 0;
    }

    void addEdge(int from, int to, int cap, int cost) {
        int idx = totalEdges++;
        edgeStart[idx] = from;
        edgeEnd[idx] = to;
        edgeXor[idx] = from ^ to;
        edgeWeight[idx] = cost;
        edgeCapacity[idx * 2] = cap;
        adjacency[from].add(idx * 2);
        adjacency[to].add(idx * 2 + 1);
    }

    int[] queueArray;
    int queueStart, queueEnd, queueCount;
    boolean[] inQueueFlag;

    void pushToQueue(int node) {
        if (inQueueFlag[node]) return;
        if (queueStart + queueEnd == queueArray.length) {
            if (queueCount * 2 <= queueArray.length) {
                System.arraycopy(queueArray, queueStart, queueArray, 0, queueCount);
            } else {
                int[] temp = new int[queueArray.length * 2];
                System.arraycopy(queueArray, queueStart, temp, 0, queueCount);
                queueArray = temp;
            }
            queueStart = 0;
        }
        queueArray[queueStart + queueEnd++] = node;
        inQueueFlag[node] = true;
    }

    int popFromQueue() {
        int node = queueArray[queueStart++];
        queueCount--;
        inQueueFlag[node] = false;
        return node;
    }

    boolean findShortestPath(int source, int sink) {
        Arrays.fill(potential, INF);
        potential[source] = 0;
        queueStart = queueEnd = 0;
        pushToQueue(source);

        while (queueCount > 0) {
            int current = popFromQueue();
            int newDist = distance[current] + 1;

            for (int edgeIndex : adjacency[current]) {
                if (edgeCapacity[edgeIndex] > 0) {
                    int edgeId = edgeIndex >> 1;
                    int cost = (edgeIndex & 1) == 0 ? edgeWeight[edgeId] : -edgeWeight[edgeId];
                    int newPotential = potential[current] + cost;
                    int neighbor = current ^ edgeXor[edgeId];

                    if (potential[neighbor] > newPotential || 
                        (potential[neighbor] == newPotential && distance[neighbor] > newDist)) {
                        potential[neighbor] = newPotential;
                        distance[neighbor] = newDist;
                        predecessor[neighbor] = edgeIndex;
                        pushToQueue(neighbor);
                    }
                }
            }
        }
        return potential[sink] != INF;
    }

    void augmentFlow(int source, int sink) {
        int minCapacity = INF;
        for (int node = sink; node != source; node ^= edgeXor[predecessor[node] >> 1]) {
            minCapacity = Math.min(minCapacity, edgeCapacity[predecessor[node]]);
        }
        for (int node = sink; node != source; node ^= edgeXor[predecessor[node] >> 1]) {
            int idx = predecessor[node];
            edgeCapacity[idx] -= minCapacity;
            edgeCapacity[idx ^ 1] += minCapacity;
        }
    }

    void augmentUnitFlow(int source, int sink) {
        for (int node = sink; node != source; node ^= edgeXor[predecessor[node] >> 1]) {
            int idx = predecessor[node];
            edgeCapacity[idx]--;
            edgeCapacity[idx ^ 1]++;
        }
    }

    int calculateMinCostFlow(int source, int sink) {
        while (findShortestPath(source, sink)) {
            augmentUnitFlow(source, sink);
        }
        int totalCost = 0;
        for (int i = 0; i < totalEdges; i++) {
            totalCost += edgeWeight[i] * edgeCapacity[i * 2 + 1];
        }
        return totalCost;
    }

    void execute() {
        try {
            int n = reader.readInt();
            int m = reader.readInt();
            int k = reader.readInt();
            int c = reader.readInt();
            int d = reader.readInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) {
                special[i] = reader.readInt() - 1;
            }

            List<Integer>[] graph = new ArrayList[n];
            for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = reader.readInt() - 1;
                int v = reader.readInt() - 1;
                graph[u].add(v);
                graph[v].add(u);
            }

            int timeSteps = k + 1;
            int totalVertices = n * timeSteps + 1;
            int totalEdgesCount = k + (m * 2 * k + n) * (timeSteps - 1);

            prepare(totalVertices, totalEdgesCount);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < timeSteps - 1; t++) {
                    int u = i * timeSteps + t;
                    for (int neighbor : graph[i]) {
                        int v = neighbor * timeSteps + t + 1;
                        for (int x = 1; x <= k; x++) {
                            addEdge(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < timeSteps - 1; t++) {
                    int u = i * timeSteps + t;
                    int v = u + 1;
                    addEdge(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                addEdge(totalVertices - 1, special[i] * timeSteps, 1, 0);
            }

            println(calculateMinCostFlow(totalVertices - 1, 0 * timeSteps + timeSteps - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
